// @Failure      500 {object} errorBody
// @Failure      503 {object} errorBody
func (a *app) libraryFacets(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "library id must be an integer", false)
		return
	}
	if a.deps.LibraryFacets == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "facets endpoint disabled", false)
		return
	}
	// The caller's scope (6.2): the visibility conjunct rides the requesting
	// viewer — a denied library serves nothing.
	v, ctx := a.viewerFor(r)
	if _, err := a.deps.Store.GetLibrary(ctx, id, v); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", "library "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	keys, values, counts := a.deps.LibraryFacets(id)
	dtos := make([]facetDTO, 0, len(keys))
	for i, key := range keys {
		vals := make([]facetValueDTO, 0, len(values[i]))
		for j, val := range values[i] {
			vals = append(vals, facetValueDTO{Value: val, Count: counts[i][j]})
		}
		dtos = append(dtos, facetDTO{Key: key, Values: vals})
	}
	writeJSON(w, http.StatusOK, facetsResponse{Facets: dtos})
}

// facetFilters is the parsed facet filter trio (library-facets delta): each
// field absent/empty = no filter on that key.
