// facetFilter intersects the fetched rows with the resolved facet id set
// (browse-scale 3.2's in-Go filter): rows whose id the set carries survive,
// in the fetched order — the intersection never reorders, so both the store's
// path order (the sort=path opt-out) and the scored default's input order
// compose untouched. An empty set (unknown facet value) serves an empty
// listing — 200 empty, never an error.
func facetFilter[T any](rows []T, ids map[string]bool, id func(T) string) []T {
	out := make([]T, 0, len(rows))
	for _, row := range rows {
		if ids[id(row)] {
			out = append(out, row)
		}
	}
	return out
}
